/*
A = <T , P>
                    where 
                    T: ℝ ^ 3: a sequence
                    P: ℝ ^ 3: a sequence 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT A;

    heartlib(
        const Eigen::Matrix<double, 3, 1> & T,
        const Eigen::Matrix<double, 3, 1> & P)
    {

        // A = <T , P>
        A = (T).dot(P);
    }
};

