outputs.matlab:
function output = heartlib(T, P)
% output = heartlib(T, P)
%
%    A = <T , P>
%                        where 
%                        T: ℝ ^ 3: a sequence
%                        P: ℝ ^ 3: a sequence 
    T = reshape(T,[],1);
    P = reshape(P,[],1);

    assert( numel(T) == 3 );
    assert( numel(P) == 3 );

    % A = <T , P>

    A = (P)' * (T);
    output.A = A;
end

